import { Dropdown } from "react-bootstrap";
import { useTranslation } from "react-i18next";
import { useNavigate } from "react-router-dom";
import jsondata from "../json/Type_of_phrase_level1.json";
import { useEffect, useRef, useState } from "react";
import arrayShuffle from "array-shuffle";
import { Button, Slider } from "@mui/material";

function Level1() {
  var [sentno, setSentno] = useState(0);
  const [allsent, setAllsent] = useState(
    arrayShuffle(Object.values(jsondata.data))
  );

  const [currsent, setCurrsent] = useState("");
  const [curradjphrase, setCurradjphrase] = useState([]);
  const [curradvphrase, setCurradvphrase] = useState([]);
  const [currnounphrase, setCurrnounphrase] = useState([]);
  var [selectedphrasetype, setSelectedphrasetype] = useState("");
  var [selectedphrase, setSelectedphrase] = useState("");

  const { t, i18n } = useTranslation();
  const navigate = useNavigate();

  const [isClicked, setIsClicked] = useState(false);
  const [currfeedback, setCurrfeedback] = useState();

  const [flag, setFlag] = useState(true);
  const [flag1, setFlag1] = useState(false);
  const [flag2, setFlag2] = useState(true);
  const [flag3, setFlag3] = useState(false);

  const [check, setCheck] = useState(false);
  const [check1, setCheck1] = useState(false);
  const [check2, setCheck2] = useState(false);

  var [score, setScore] = useState(0);

  useEffect(() => {
    if (sentno >= allsent.length) {
      setFlag3(true);
    } else {
      const current = allsent[sentno];
      setCurrsent(current.sentence);
      setCurradjphrase(current.phrases_types.adjective || []);
      setCurradvphrase(current.phrases_types.adverb || []);
      setCurrnounphrase(current.phrases_types.noun || []);
    }
  }, [allsent, sentno]);

  const getColoredText = () => {
    let sentence = currsent;
    let allPhrases = [
      ...curradjphrase.map((p) => ({ phrase: p, type: "adjective" })),
      ...curradvphrase.map((p) => ({ phrase: p, type: "adverb" })),
      ...currnounphrase.map((p) => ({ phrase: p, type: "noun" })),
    ];

    allPhrases.sort((a, b) => b.phrase.length - a.phrase.length); // longest first
    let used = new Set();

    allPhrases.forEach(({ phrase, type }) => {
      const regex = new RegExp(`(${phrase})`, "i");
      if (!used.has(phrase) && regex.test(sentence)) {
        sentence = sentence.replace(
          regex,
          `<span class="phrase ${type}" >$1</span>`
        );
        used.add(phrase);
      }
    });

    return sentence;
  };

  // Handle click globally
  useEffect(() => {
    const handleClick = (e) => {
      if (isClicked) return;
      const el = e.target;
      console.log("el ==>", el.classList);
      if (!el.classList.contains("phrase")) return;

      // Avoid double clicking
      if (el.classList.contains("clicked")) return;

      el.classList.add("clicked");

      const type = [...el.classList].find((cls) =>
        ["adjective", "adverb", "noun"].includes(cls)
      );

      const text = el.textContent;
      console.log("Clicked type:", type, "Phrase:", text);
      setSelectedphrase(text);
      setSelectedphrasetype(type);
      setFlag(false);
      setFlag1(false);

      setIsClicked(true);

      console.log("el.classlist ==>", el.classList);
    };

    document.addEventListener("click", handleClick);
    return () => {
      document.removeEventListener("click", handleClick);
    };
  }, []);

  useEffect(() => {
    if (check && check1 && check2) {
      setFlag2(false);
    }
  }, [check, check1, check2]);

  const level2select = () => {
    navigate("/launchpage/englishactivity/level2");
  };

  const handleadjbtn = (e) => {
    const val = e.currentTarget.id;
    setFlag1(true);

    if (selectedphrasetype === val) {
      setCurrfeedback(
        <>
          Correct! &nbsp; <b style={{ color: "green" }}>{selectedphrase}</b>{" "}
          &nbsp; is a correct &nbsp;<b>adjective</b>&nbsp;phrase.
        </>
      );
      setCheck(true);
    } else {
      setCurrfeedback(
        <div style={{ textAlign: "center" }}>
          Incorrect! <b style={{ color: "red" }}>{selectedphrase}</b> is not a
          valid <b>adjective</b> phrase.
          <br />
          <b>Hint:</b> Adjective phrases are groups of words that act as
          adjectives.
        </div>
      );
    }
  };

  const handleadvbtn = (e) => {
    const val = e.currentTarget.id;
    setFlag(true);
    setFlag1(true);

    if (selectedphrasetype === val) {
      setCurrfeedback(
        <>
          Correct! &nbsp; <b style={{ color: "green" }}>{selectedphrase}</b>{" "}
          &nbsp; is a correct &nbsp;<b>adverb</b>&nbsp;phrase.
        </>
      );
      setCheck1(true);
    } else {
      setCurrfeedback(
        <div style={{ textAlign: "center" }}>
          Incorrect! <b style={{ color: "red" }}>{selectedphrase}</b> is not a
          valid <b>adverb</b> phrase.
          <br />
          <b>Hint:</b> Phrases which do the work of an adverb in sentence are
          called adverb phrase.
        </div>
      );
    }
  };

  const handlenounbtn = (e) => {
    const val = e.currentTarget.id;
    setFlag(true);
    setFlag1(true);

    if (selectedphrasetype === val) {
      setCurrfeedback(
        <>
          Correct! &nbsp; <b style={{ color: "green" }}>{selectedphrase}</b>{" "}
          &nbsp; is a correct &nbsp;<b>noun</b>&nbsp;phrase.
        </>
      );
      setCheck2(true);
    } else {
      setCurrfeedback(
        <div style={{ textAlign: "center" }}>
          Incorrect! <b style={{ color: "red" }}>{selectedphrase}</b> is not a
          valid <b>noun</b> phrase.
          <br />
          <b>Hint:</b> A phrase which acts like a noun in a sentence is called a
          noun phrase.
        </div>
      );
    }
  };

  const handlenextbtn = () => {
    sentno = sentno + 1;
    setSentno(sentno);
    setCheck(false);
    setCheck1(false);
    setCheck2(false);
    setFlag(true);
    setFlag1(false);
    setFlag2(true);
    score=score+1;
    setScore(score);
  };

  const handleskipbtn = () => {
    sentno = sentno + 1;
    setSentno(sentno);
    setCheck(false);
    setCheck1(false);
    setCheck2(false);
    setFlag(true);
    setFlag1(false);
    setFlag2(true);

  };

  const restartbtn = () => {
    window.location.reload();
  };

  return (
    <div
      className="scrollbar-primary row d-flex"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        {flag3 ? (
          <div
            className="scrollbar-primary"
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF 0% 0% no-repeat padding-box",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
              position: "relative",
            }}
          >
            <div className="d-flex justify-content-between align-items-center mb-3">
              <div className="flex-grow-1 text-center">
                <h5>
                  <b>{t("level_1_title")}</b>
                </h5>
              </div>
              <Dropdown className="d-flex justify-content-end">
                <Dropdown.Toggle variant="success" id="dropdown-basic">
                  {t("levels")}
                </Dropdown.Toggle>

                <Dropdown.Menu>
                  <Dropdown.Item href="#/action-1" disabled="true">
                    {t("level_1")}
                  </Dropdown.Item>
                  <Dropdown.Item onClick={level2select}>
                    {t("level_2")}
                  </Dropdown.Item>
                </Dropdown.Menu>
              </Dropdown>
            </div>

            <div
              className="d-flex justify-content-center align-items-center"
              style={{ minHeight: "50vh" }}
            >
              <div
                className="col-sm-6 text-center "
                style={{
                  boxShadow: "rgba(0, 0, 0, 0.24) 0px 3px 8px",
                  padding: "7vh 4vh 7vh 4vh",
                  backgroundColor: "#EDF6FA",
                }}
              >
                <p style={{ fontWeight: "bolder" }}>
                  You have scored {score} out of {allsent.length} sentences.
                </p>
                <div>
                  <Button variant="contained" onClick={restartbtn}>
                    {t("restart")}
                  </Button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div
            className="scrollbar-primary"
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
              position: "relative",
            }}
          >
            <div className="row-md-auto d-flex text-center">
              <div className="col text-center">
                <h5 style={{ marginTop: "1vh" }}>
                  <b>{t("level_1_title")}</b>
                </h5>
              </div>
              <div className="d-flex justify-content-end">
                <Dropdown className="d-flex justify-content-end">
                  <Dropdown.Toggle variant="success" id="dropdown-basic">
                    {t("levels")}
                  </Dropdown.Toggle>

                  <Dropdown.Menu>
                    <Dropdown.Item href="#/action-1" disabled="true">
                      {t("level_1")}
                    </Dropdown.Item>
                    <Dropdown.Item onClick={level2select}>
                      {t("level_2")}
                    </Dropdown.Item>
                  </Dropdown.Menu>
                </Dropdown>
              </div>
            </div>

            <div
              className="d-flex align-items-center"
              style={{ marginTop: "7%" }}
            >
              <span className="me-3">Sentence</span>
              <Slider
                defaultValue={1}
                step={1}
                min={0}
                max={allsent.length}
                value={sentno + 1}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />
              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "60px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  fontSize: "16px",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {sentno + 1}/{allsent.length}
              </span>
            </div>

            <div
              className="row-md-auto"
              style={{
                backgroundColor: "#EDF6FA",
                borderRadius: "13px",
                boxShadow: "0px 4px 7px #00000029",
                flexWrap: "wrap",
                justifyContent: "center",
                alignItems: "center",
                padding: "2%",
                marginTop: "1vh",
                textAlign: "center",
                position: "relative",
              }}
            >
              {" "}
              <div dangerouslySetInnerHTML={{ __html: getColoredText() }} />
              <div className="mt-5 d-flex justify-content-around">
                <Button
                  variant="contained"
                  sx={{ backgroundColor: "#F5B946", color: "black" }}
                  id="adjective"
                  onClick={handleadjbtn}
                  disabled={flag}
                >
                  <strong>Adjective</strong>
                </Button>
                <Button
                  variant="contained"
                  sx={{ backgroundColor: "#F5B946", color: "black" }}
                  id="noun"
                  onClick={handlenounbtn}
                  disabled={flag}
                >
                  <strong>Noun</strong>
                </Button>
                <Button
                  variant="contained"
                  sx={{ backgroundColor: "#F5B946", color: "black" }}
                  id="adverb"
                  onClick={handleadvbtn}
                  disabled={flag}
                >
                  <strong>Adverb</strong>
                </Button>
              </div>
            </div>

            <div className="d-flex justify-content-around mt-4">
              <Button
                variant="contained"
                sx={{ backgroundColor: "#0F477E" }}
                onClick={handleskipbtn}
              >
                Skip
              </Button>

              <Button
                variant="contained"
                onClick={handlenextbtn}
                sx={{ backgroundColor: "#0F477E" }}
                disabled={flag2}
              >
                Next
              </Button>
            </div>

            <div
              className="row justify-content-center"
              style={{ marginTop: "2vh" }}
            >
              {flag1 ? (
                <div
                  className="d-flex justify-content-center align-items-center"
                  style={{
                    width: "auto",
                    height: "auto",
                    background: "rgb(255, 255, 255)",
                    boxShadow: "rgba(0, 0, 0, 0.5) 0px 0px 10px",
                    borderRadius: "50px",
                    padding: "1rem",
                  }}
                >
                  {currfeedback}
                </div>
              ) : (
                ""
              )}
            </div>
          </div>
        )}
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center"
            style={{
              background: "#002F65",
              borderRadius: "10px 10px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "1.3rem",
              fontWeight: "bolder",
            }}
          >
            {t("instruction")}
          </div>

          <div style={{ maxHeight: "50vh", padding: "2%" }}>
            <div>
              <ul>
                <li>{t("instruction_1_1")}</li>
                <li>{t("instruction_1_2")}</li>
                <li>{t("instruction_1_3")}</li>
                <li>{t("instruction_1_4")}</li>
                <li>{t("instruction_1_5")}</li>
                <li>{t("instruction_1_6")}</li>
                <li>{t("instruction_1_7")}</li>
                <li>{t("instruction_1_8")}</li>
                <li>{t("instruction_1_9")}</li>
                <li>{t("instruction_1_10")}</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Level1;
