// *****************************************************************************************
import { Dropdown } from "react-bootstrap";
import { useTranslation } from "react-i18next";
import { useNavigate } from "react-router-dom";
import jsondata from "../json/Type_of_phrase_level1_1.json";
import { useEffect, useRef, useState } from "react";
import arrayShuffle from "array-shuffle";
import { Button, Slider } from "@mui/material";

function Level1() {
  var [sentno, setSentno] = useState(0);
  const [allsent, setAllsent] = useState(
    arrayShuffle(Object.values(jsondata.data))
  );

  const [currsent, setCurrsent] = useState("");
  var [currphrase, setCurrphrase] = useState("");
  const [currtypephrase, setCurrtypephrase] = useState("");
  const [currnounphrase, setCurrnounphrase] = useState([]);
  var [selectedphrasetype, setSelectedphrasetype] = useState("");
  var [selectedphrase, setSelectedphrase] = useState("");

  const { t, i18n } = useTranslation();
  const navigate = useNavigate();

  const [isClicked, setIsClicked] = useState(false);
  const [currfeedback, setCurrfeedback] = useState();
  const [showmsg, setShowmsg] = useState();

  const [flag, setFlag] = useState(true);
  const [flag1, setFlag1] = useState(false);
  const [flag2, setFlag2] = useState(true);
  const [flag3, setFlag3] = useState(false);
  const [flag4, setFlag4] = useState(false);

  const [check, setCheck] = useState(false);
  const [check1, setCheck1] = useState(false);
  const [check2, setCheck2] = useState(false);

  var [score, setScore] = useState(0);

  useEffect(() => {
    if (sentno >= allsent.length) {
      setFlag3(true);
    } else {
      const current = allsent[sentno];
      setCurrsent(current.sentence);
      currphrase = current.phrase;
      setCurrphrase(currphrase);
      setCurrtypephrase(current.type_of_phrase);
    }
  }, [allsent, sentno]);

  // const getColoredText = () => {
  //   let sentence = currsent;
  //   let phrase = currphrase;

  //   if (sentence.includes(phrase)) {
  //     const index = sentence.indexOf(phrase);

  //     const before = sentence.slice(0, index).trimEnd(); // "I met a man"
  //     const after = phrase; // "covered in mud"
  //     const punctuation = sentence.slice(index + phrase.length); // e.g., "."

  //     const result =
  //       `<span class="hover-dotted remaining">${before} </span>` +
  //       `<span class="hover-dotted phrase">${after}</span>` +
  //       `<span class="hover-dotted phrase">${punctuation}</span>`;

  //     return result;
  //   } else {
  //     console.log("Phrase not found in sentence.");
  //     return sentence;
  //   }
  // };

  // Handle click globally

  const getColoredText = () => {
    let sentence = currsent;
    let phrase = currphrase;

    if (sentence.includes(phrase)) {
      const index = sentence.indexOf(phrase);

      const before = sentence.slice(0, index).trimEnd(); // "I met a man"
      const after = phrase; // "covered in mud"
      const punctuation = sentence.slice(index + phrase.length); // e.g., "."

      const getSpan = (content, type) => {
        const base = "hover-dotted";
        const isClicked = selectedphrase === content.trim();
        return `<span class="${base} ${type} ${
          isClicked ? "clicked-underline" : ""
        }">${content}</span>`;
      };

      const result =
        getSpan(before + " ", "remaining") +
        getSpan(after, "phrase") +
        getSpan(punctuation, "phrase");

      return result;
    } else {
      console.log("Phrase not found in sentence.");
      return sentence;
    }
  };

  useEffect(() => {
    const handleClick = (e) => {
      console.log(currphrase);
      let el = e.target;

      // If clicked on a text node, get the parent span
      if (el.nodeType === Node.TEXT_NODE) {
        //If the text inside the span is clicked then get its parent span
        el = el.parentElement;
      }

      if (!el || !el.classList.contains("hover-dotted")) return; // ensures that clicked text have class hover-dotted
      // Remove underline class from previously clicked element if any
      const prevClicked = document.querySelector(".clicked-underline");
      if (prevClicked) {
        prevClicked.classList.remove("clicked-underline");
      }

      // Add underline class to the clicked element
      el.classList.add("clicked-underline");

      const text = el.textContent.trim();

      console.log("text ==>", text, "currphrase ==>", currphrase);
      setFlag4(true);
      if (text === currphrase) {
        setShowmsg(
          <div style={{ textAlign: "center" }}>
            Correct! <b style={{ color: "green" }}>{text}</b> is a phrase.
            <br></br>
            Now, select the type of phrase.
          </div>
        );
        setFlag(false);
      } else {
        setShowmsg(
          <div style={{ textAlign: "center" }}>
            Incorrect! &nbsp;<b style={{ color: "red" }}>{text}</b> &nbsp;is not
            a phrase.<br></br>
            <b>Hint:</b> A Phrase is a group of words which may have a partial
            subject or verb but not both.
          </div>
        );
        setFlag(true);
      }

      setSelectedphrase(text);
      setFlag1(false);

      setIsClicked(true);
    };

    document.addEventListener("click", handleClick);
    return () => {
      document.removeEventListener("click", handleClick);
    };
  }, [sentno]);

  useEffect(() => {
    if (check && check1 && check2) {
      setFlag2(false);
    }
  }, [check, check1, check2]);

  const level2select = () => {
    navigate("/launchpage/englishactivity/level2");
  };

  const handleadjbtn = (e) => {
    const val = e.currentTarget.id;
    setFlag1(true);
    setFlag4(false);
    if (currtypephrase === val) {
      setCurrfeedback(
        <>
          Correct! &nbsp; <b style={{ color: "green" }}>{selectedphrase}</b>{" "}
          &nbsp; is a correct &nbsp;<b>adjective</b>&nbsp;phrase.
        </>
      );
      setFlag(true);
      setCheck(true);
      setFlag2(false);
    } else {
      setCurrfeedback(
        <div style={{ textAlign: "center" }}>
          Incorrect! <b style={{ color: "red" }}>{selectedphrase}</b> is not a
          valid <b>adjective</b> phrase.
          <br />
          <b>Hint:</b> Adjective phrases are groups of words that act as
          adjectives.
        </div>
      );
    }
  };

  const handleadvbtn = (e) => {
    const val = e.currentTarget.id;
    setFlag1(true);
    setFlag4(false);

    if (currtypephrase === val) {
      setCurrfeedback(
        <>
          Correct! &nbsp; <b style={{ color: "green" }}>{selectedphrase}</b>{" "}
          &nbsp; is a correct &nbsp;<b>adverb</b>&nbsp;phrase.
        </>
      );
      setFlag(true);
      setCheck1(true);
      setFlag2(false);
    } else {
      setCurrfeedback(
        <div style={{ textAlign: "center" }}>
          Incorrect! <b style={{ color: "red" }}>{selectedphrase}</b> is not a
          valid <b>adverb</b> phrase.
          <br />
          <b>Hint:</b> Phrases which do the work of an adverb in a sentence are
          called adverb phrases.
        </div>
      );
    }
  };

  const handlenounbtn = (e) => {
    const val = e.currentTarget.id;
    setFlag1(true);
    setFlag4(false);
    if (currtypephrase === val) {
      setCurrfeedback(
        <>
          Correct! &nbsp; <b style={{ color: "green" }}>{selectedphrase}</b>{" "}
          &nbsp; is a correct &nbsp;<b>noun</b>&nbsp;phrase.
        </>
      );
      setFlag(true);
      setCheck2(true);
      setFlag2(false);
    } else {
      setCurrfeedback(
        <div style={{ textAlign: "center" }}>
          Incorrect! <b style={{ color: "red" }}>{selectedphrase}</b> is not a
          valid <b>noun</b> phrase.
          <br />
          <b>Hint:</b> A phrase which acts like a noun in a sentence is called a
          noun phrase.
        </div>
      );
    }
  };

  const handlenextbtn = () => {
    sentno = sentno + 1;
    setSentno(sentno);
    setCheck(false);
    setCheck1(false);
    setCheck2(false);
    setFlag(true);
    setFlag1(false);
    setFlag2(true);
    setFlag4(false);
    score = score + 1;
    setScore(score);
  };

  const handleskipbtn = () => {
    sentno = sentno + 1;
    setSentno(sentno);
    setCheck(false);
    setCheck1(false);
    setCheck2(false);
    setFlag(true);
    setFlag1(false);
    setFlag2(true);
    setFlag4(false);
  };

  const restartbtn = () => {
    window.location.reload();
  };

  return (
    <div
      className="scrollbar-primary row d-flex"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        {flag3 ? (
          <div
            className="scrollbar-primary"
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF 0% 0% no-repeat padding-box",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
              position: "relative",
            }}
          >
            <div className="d-flex justify-content-between align-items-center mb-3">
              <div className="flex-grow-1 text-center">
                <h5>
                  <b>{t("level_1_title")}</b>
                </h5>
              </div>
              <Dropdown className="d-flex justify-content-end">
                <Dropdown.Toggle variant="success" id="dropdown-basic">
                  {t("levels")}
                </Dropdown.Toggle>

                <Dropdown.Menu>
                  <Dropdown.Item href="#/action-1" disabled="true">
                    {t("level_1")}
                  </Dropdown.Item>
                  <Dropdown.Item onClick={level2select}>
                    {t("level_2")}
                  </Dropdown.Item>
                </Dropdown.Menu>
              </Dropdown>
            </div>

            <div
              className="d-flex justify-content-center align-items-center"
              style={{ minHeight: "50vh" }}
            >
              <div
                className="col-sm-6 text-center "
                style={{
                  boxShadow: "rgba(0, 0, 0, 0.24) 0px 3px 8px",
                  padding: "7vh 4vh 7vh 4vh",
                  backgroundColor: "#EDF6FA",
                }}
              >
                <p style={{ fontWeight: "bolder" }}>
                  You have scored {score} out of {allsent.length} sentences.
                </p>
                <div>
                  <Button variant="contained" onClick={restartbtn}>
                    {t("restart")}
                  </Button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div
            className="scrollbar-primary"
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
              position: "relative",
            }}
          >
            <div className="row-md-auto d-flex text-center">
              <div className="col text-center">
                <h5 style={{ marginTop: "1vh" }}>
                  <b>{t("level_1_title")}</b>
                </h5>
              </div>
              <div className="d-flex justify-content-end">
                <Dropdown className="d-flex justify-content-end">
                  <Dropdown.Toggle variant="success" id="dropdown-basic">
                    {t("levels")}
                  </Dropdown.Toggle>

                  <Dropdown.Menu>
                    <Dropdown.Item href="#/action-1" disabled="true">
                      {t("level_1")}
                    </Dropdown.Item>
                    <Dropdown.Item onClick={level2select}>
                      {t("level_2")}
                    </Dropdown.Item>
                  </Dropdown.Menu>
                </Dropdown>
              </div>
            </div>

            <div
              className="d-flex align-items-center"
              style={{ marginTop: "7%" }}
            >
              <span className="me-3">Sentence</span>
              <Slider
                defaultValue={1}
                step={1}
                min={0}
                max={allsent.length}
                value={sentno + 1}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />
              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "60px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  fontSize: "16px",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {sentno + 1}/{allsent.length}
              </span>
            </div>

            <div
              className="row-md-auto"
              style={{
                backgroundColor: "#EDF6FA",
                borderRadius: "13px",
                boxShadow: "0px 4px 7px #00000029",
                flexWrap: "wrap",
                justifyContent: "center",
                alignItems: "center",
                padding: "2%",
                marginTop: "1vh",
                textAlign: "center",
                position: "relative",
              }}
            >
              {" "}
              <div
                className="sentence-wrapper"
                dangerouslySetInnerHTML={{ __html: getColoredText() }}
              ></div>
              <div className="mt-5 d-flex justify-content-around">
                <Button
                  variant="contained"
                  sx={{ backgroundColor: "#F5B946", color: "black" }}
                  id="adjective"
                  onClick={handleadjbtn}
                  disabled={flag}
                >
                  <strong>Adjective</strong>
                </Button>
                <Button
                  variant="contained"
                  sx={{ backgroundColor: "#F5B946", color: "black" }}
                  id="noun"
                  onClick={handlenounbtn}
                  disabled={flag}
                >
                  <strong>Noun</strong>
                </Button>
                <Button
                  variant="contained"
                  sx={{ backgroundColor: "#F5B946", color: "black" }}
                  id="adverb"
                  onClick={handleadvbtn}
                  disabled={flag}
                >
                  <strong>Adverb</strong>
                </Button>
              </div>
            </div>

            <div className="d-flex justify-content-around mt-4">
              <Button
                variant="contained"
                sx={{ backgroundColor: "#0F477E" }}
                onClick={handleskipbtn}
              >
                Skip
              </Button>

              <Button
                variant="contained"
                onClick={handlenextbtn}
                sx={{ backgroundColor: "#0F477E" }}
                disabled={flag2}
              >
                Next
              </Button>
            </div>

            <div
              className="row justify-content-center"
              style={{ marginTop: "2vh" }}
            >
              {flag1 ? (
                <div
                  className="d-flex justify-content-center align-items-center"
                  style={{
                    width: "auto",
                    height: "auto",
                    background: "rgb(255, 255, 255)",
                    boxShadow: "rgba(0, 0, 0, 0.5) 0px 0px 10px",
                    borderRadius: "50px",
                    padding: "1rem",
                  }}
                >
                  {currfeedback}
                </div>
              ) : (
                ""
              )}
              {flag4 ? (
                <div
                  className="d-flex justify-content-center align-items-center"
                  style={{
                    width: "auto",
                    height: "auto",
                    background: "rgb(255, 255, 255)",
                    boxShadow: "rgba(0, 0, 0, 0.5) 0px 0px 10px",
                    borderRadius: "50px",
                    padding: "1rem",
                  }}
                >
                  {showmsg}
                </div>
              ) : (
                ""
              )}
            </div>
          </div>
        )}
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center"
            style={{
              background: "#002F65",
              borderRadius: "10px 10px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "1.3rem",
              fontWeight: "bolder",
            }}
          >
            {t("instruction")}
          </div>

          <div style={{ maxHeight: "50vh", padding: "2%" }}>
            <div>
              <ul>
                <li>{t("instruction_1_1")}</li>
                <li>{t("instruction_1_2")}</li>
                <li>{t("instruction_1_3")}</li>
                <li>{t("instruction_1_4")}</li>
                <li>{t("instruction_1_5")}</li>
                <li>{t("instruction_1_6")}</li>
                <li>{t("instruction_1_7")}</li>
                <li>{t("instruction_1_8")}</li>
                <li>{t("instruction_1_9")}</li>
                <li>{t("instruction_1_10")}</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Level1;
