 function processParagraph(paragraph, allFeedbackWords) {
   const quantifiers = allFeedbackWords.map((q) => q.phrase.toLowerCase());

   const text = paragraph.join(" ");
   const words = text.split(/\s+/); // Tokenize by whitespace

   const result = [];
   let i = 0;

   while (i < words.length) {
     let found = false;

     // Try matching up to 4-word phrases
     for (let len = 4; len >= 1; len--) {
       const chunkWords = words.slice(i, i + len);
       if (chunkWords.length < len) continue;

       let punctuation = "";
       const lastWord = chunkWords[len - 1];

       // Extract punctuation from the end (if any)
       const match = lastWord.match(/^(.+?)([.,!?])$/);
       if (match) {
         chunkWords[len - 1] = match[1]; // strip punctuation
         punctuation = match[2]; // store punctuation
       }

       const chunk = chunkWords.join(" ");
       const chunkLower = chunk.toLowerCase();

       if (quantifiers.includes(chunkLower)) {
         result.push({
           text: chunk, // no punctuation here
           isDraggable: true,
         });

         if (punctuation) {
           result.push({
             text: punctuation,
             isDraggable: false,
           });
         }

         i += len;
         found = true;
         break;
       }
     }

     if (!found) {
       result.push({
         text: words[i],
         isDraggable: false,
       });
       i++;
     }
   }

   return result;
 }

